css:
.sl__rule { display: block; width: 3.5rem; height: 3px; border-radius: 3px; background: linear-gradient(90deg, var(--bff-leaf, #6b8e36), var(--bff-gold, #eec02b)); margin-bottom: clamp(1.4rem, 3vw, 2.2rem); }
.sl__h { margin: 0 0 .5em; font-size: clamp(2.1rem, 1.2rem + 3.4vw, 3.7rem); line-height: 1.08; letter-spacing: -.015em; }
.sl__item { display: grid; gap: 1rem 3rem; padding: 2rem 0; border-top: 1px solid var(--bff-line, rgba(21,38,26,.22)); }
@media (min-width: 62rem) { .sl__item { grid-template-columns: minmax(0, 17rem) minmax(0, 1fr); } }
.sl__when { margin: 0 0 .6rem; }
.sl__day { margin: 0; font-family: var(--os-font-heading); font-size: clamp(1.7rem, 1.2rem + 1.6vw, 2.5rem); line-height: 1.05; color: var(--os-color-heading); }
.sl__meta { margin: .5rem 0 0; font-size: 1rem; line-height: 1.05; color: var(--bff-ink-2, #3f4f3b); }
.sl__next { display: inline; }
.sl__next b { color: var(--os-color-link); font-weight: 700; }
.sl__title { margin: 0 0 .5em; font-size: clamp(1.45rem, 1.1rem + 1.2vw, 2rem); line-height: 1.15; letter-spacing: -.015em; }
.sl__note { margin: 1em 0; max-width: 62ch; }
.sl a { display: inline-flex; text-decoration: none; }
.sl__btn { display: inline-flex; align-items: center; justify-content: center; padding: .6em 1.1em; border-radius: 999px; font: 700 .95rem/1.1 var(--os-font-body); color: var(--os-color-heading); border: 2px solid transparent; }
.sl__btn--a { color: #15261a; background: linear-gradient(100deg, var(--bff-btn-a, #a7c25a), var(--bff-btn-b, #f2cb4a) 60%, var(--bff-btn-a, #a7c25a)) 0 0 / 220% 100%; transition: background-position .4s; }
.sl__btn--a:hover { background-position: 100% 0; }
.sl__btn--b { border-color: currentColor; }
.sl__btn--b:hover { background: var(--os-color-heading); color: var(--os-color-background); }
.sl__foot { margin: 1.6rem 0 1em; max-width: 62ch; }
.sl__foot a { vertical-align: middle; }
@media (max-width: 767px) { .sl__btn { min-height: 2.75rem; } }
@media (prefers-reduced-motion: reduce) { .sl__btn--a { transition: none; } }

js:
var days=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
root.querySelectorAll('.sl__next').forEach(function(el){
  var d=days.indexOf(el.getAttribute('data-weekday')); if(d<0) return;
  var t=new Date(new Date().toLocaleString('en-US',{timeZone:'America/Denver'})); var add=(d-t.getDay()+7)%7; var n=new Date(t.getFullYear(),t.getMonth(),t.getDate()+add);
  var s=n.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'});
  el.textContent='Next: '; var b=document.createElement('b'); b.textContent=s; el.appendChild(b);
});
var sec=document.getElementById('sign-up')||document.querySelector('[data-os-anchor="sign-up"]');
if(!sec||!window.HTMLDialogElement)return;
var dlg=document.createElement('dialog');dlg.setAttribute('aria-label','Sign up to volunteer');
dlg.style.cssText='width:min(40rem,calc(100% - 2rem));max-height:calc(100dvh - 2rem);padding:0;border:0;border-radius:14px;background:var(--bff-raised, #f3f1e2);color:inherit;overflow:auto;box-shadow:0 20px 60px rgba(0,0,0,.25)';
var x=document.createElement('button');x.type='button';x.setAttribute('aria-label','Close');x.textContent='×';
x.style.cssText='position:absolute;top:.6rem;right:.6rem;width:44px;height:44px;border-radius:50%;border:1px solid var(--bff-line, rgba(21,38,26,.25));background:transparent;font-size:1.6rem;line-height:1;cursor:pointer;color:inherit;z-index:2';
sec.parentNode.insertBefore(dlg,sec);dlg.appendChild(x);dlg.appendChild(sec);sec.style.background='transparent';
x.addEventListener('click',function(){dlg.close()});
dlg.addEventListener('click',function(e){if(e.target===dlg)dlg.close()});
function open(shift){var sel=sec.querySelector('select[name="shift"]');if(sel&&shift){for(var i=0;i<sel.options.length;i++){if(sel.options[i].text.indexOf(shift)===0){sel.selectedIndex=i;break}}}dlg.showModal();var f=sec.querySelector('input,select,textarea');if(f)f.focus()}
root.querySelectorAll('a').forEach(function(a){if((a.getAttribute('href')||'').indexOf('#sign-up')<0)return;a.addEventListener('click',function(e){e.preventDefault();var it=a.closest('.sl__item'),t=it&&it.querySelector('.sl__title');open(t?t.textContent.trim():'Something else')})});
if(location.hash==='#sign-up')open('');
